process WITTYER {
    tag "$meta.id"
    label 'process_single'

    container "quay.io/nf-core/wittyer:0.5.2"

    input:
    tuple val(meta), path(query_vcf), path(truth_vcf), path(bed), path(wittyer_config)

    output:
    tuple val(meta),    path("*.json")         , emit: report
    tuple val(meta),    path("*.vcf.gz")       , emit: bench_vcf
    tuple val(meta),    path("*.vcf.gz.tbi")   , emit: bench_vcf_tbi
    tuple val("${task.process}"), val('wittyer'), eval("dotnet /opt/Wittyer/Wittyer.dll --version | sed '1!d ; s/witty.er //'"), topic: versions, emit: versions_wittyer

    when:
    task.ext.when == null || task.ext.when

    script:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "WITTYER module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    def args  = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"
    // you can not define both bed and wittyer_config
    def regions = bed ? "-b $bed" : ""
    def config_file = wittyer_config ? "-c $wittyer_config" : ""
    if ("$truth_vcf" == "${prefix}.vcf") {
        error "Input and output names are the same, set prefix in module configuration to disambiguate!"
    }
    if ("$query_vcf" == "${prefix}.vcf") {
        error "Input and output names are the same, set prefix in module configuration to disambiguate!"
    }

    // dotnet /opt/Wittyer/Wittyer.dll might need to be replaced with new docker image
    """
    mkdir bench

    dotnet /opt/Wittyer/Wittyer.dll \\
        -t ${truth_vcf} \\
        -i ${query_vcf} \\
        -o bench \\
        ${regions} \\
        ${config_file} \\
        ${args}

    mv bench/Wittyer.Stats.json ${prefix}.json
    mv bench/*.vcf.gz ${prefix}.vcf.gz
    mv bench/*.vcf.gz.tbi ${prefix}.vcf.gz.tbi

    rm -rf bench

    """

    stub:
    // Exit if running this module with -profile conda / -profile mamba
    if (workflow.profile.tokenize(',').intersect(['conda', 'mamba']).size() >= 1) {
        error "WITTYER module does not support Conda. Please use Docker / Singularity / Podman instead."
    }
    def prefix = task.ext.prefix ?: "${meta.id}"
    if ("$truth_vcf" == "${prefix}.vcf") {
        error "Input and output names are the same, set prefix in module configuration to disambiguate!"
    }
    if ("$query_vcf" == "${prefix}.vcf") {
        error "Input and output names are the same, set prefix in module configuration to disambiguate!"
    }
    """
    touch ${prefix}.json
    echo "" | gzip > ${prefix}.vcf.gz
    touch ${prefix}.vcf.gz.tbi

    """
}

nextflow_process {

    name "Test Process WITTYER"
    script "../main.nf"
    process "WITTYER"

    tag "modules"
    tag "modules_nfcore"
    tag "wittyer"
    tag "htslib/bgziptabix"

    config "./nextflow.config"

    setup {
        run('HTSLIB_BGZIPTABIX', alias: 'HTSLIB_BGZIPTABIX_1') {
            script "../../../nf-core/htslib/bgziptabix/main.nf"

            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/chr21/simulated_sv.vcf.gz', checkIfExists: true),
                    [],
                    []
                ]
                input[1] = "decompress"
                input[2] = false
                input[3] = "vcf"
                """
            }
        }

        run('HTSLIB_BGZIPTABIX', alias: 'HTSLIB_BGZIPTABIX_2') {
            script "../../../nf-core/htslib/bgziptabix/main.nf"

            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/chr21/simulated_sv2.vcf.gz', checkIfExists: true),
                    [],
                    []
                ]
                input[1] = "decompress"
                input[2] = false
                input[3] = "vcf"
                """
            }
        }
    }

    test("human - simulatedSV - vcf") {

        when {
            process {
                """
                input[0] = HTSLIB_BGZIPTABIX_1.out.output.join(HTSLIB_BGZIPTABIX_2.out.output).map{meta, vcf1, vcf2 -> tuple(meta, vcf1, vcf2, [], [])}
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    process.out.report,
                    file(process.out.bench_vcf_tbi.get(0).get(1)).name,
                    path(process.out.bench_vcf[0][1]).vcf.variantsMD5
                    ).match() }
            )
        }

    }

    test("human - simulatedSV - vcf - bed") {

        when {
            process {
                """
                input[0] = HTSLIB_BGZIPTABIX_1.out.output
                    .join(HTSLIB_BGZIPTABIX_2.out.output)
                    .map{meta, vcf1, vcf2 ->
                        tuple(meta, vcf1, vcf2,
                            [file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/multi_intervals.bed', checkIfExists: true)],
                            [])
                        }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    process.out.report,
                    file(process.out.bench_vcf_tbi.get(0).get(1)).name,
                    path(process.out.bench_vcf[0][1]).vcf.variantsMD5
                    ).match() }
            )
        }

    }

    test("human - simulatedSV - vcf - config") {

        when {
            process {
                """
                input[0] = HTSLIB_BGZIPTABIX_1.out.output
                    .join(HTSLIB_BGZIPTABIX_2.out.output)
                    .map{meta, vcf1, vcf2 ->
                        tuple(meta, vcf1, vcf2, [],
                        // change to config file
                            [file(params.modules_testdata_base_path + 'generic/config/wittyer_config.json', checkIfExists: true)])
                        }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    process.out.report,
                    file(process.out.bench_vcf_tbi.get(0).get(1)).name,
                    path(process.out.bench_vcf[0][1]).vcf.variantsMD5
                    ).match() }
            )
        }

    }

    test("human - simulatedSV - vcf - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = HTSLIB_BGZIPTABIX_1.out.output
                    .join(HTSLIB_BGZIPTABIX_2.out.output)
                    .map{meta, vcf1, vcf2 ->
                        tuple(meta, vcf1, vcf2, [],
                            [file(params.modules_testdata_base_path + 'generic/config/wittyer_config.json', checkIfExists: true)])
                        }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

